var s=[{title:`Τι περιγράφουν τα πρότυπα`,text:`Μια καθισιά λυγίζει και ισιώνει κυρίως μαζί τα ισχία, τα γόνατα και τους αστραγάλους. Μια άρθρωση ισχίου (hinge) κινείται κυρίως στα ισχία, ενώ τα προβαδίσματα και τα step-ups φορτίζουν ένα πόδι τη φορά. Η ώθηση απομακρύνει την αντίσταση από το σώμα και η έλξη την φέρνει προς το σώμα. Σε μια μεταφορά κρατάτε ένα φορτίο σταθερό ενώ περπατάτε, οι ασκήσεις κορμού αντιστέκονται ή παράγουν κίνηση του κορμού, και η μετακίνηση καλύπτει το περπάτημα, το τρέξιμο και παρόμοιες κινήσεις.`},{title:`Γιατί μετράνε τα πρότυπα`,text:`Μία άσκηση μπορεί να προπονεί αρκετούς μυς και πρότυπα ταυτόχρονα. Ένα goblet squat προπονεί τα πόδια και τον κορμό, και μια μεταφορά με φορτίο προπονεί τη λαβή, τη στάση και τη μηχανική του βαδίσματος. Η ταξινόμηση των ασκήσεων κατά πρότυπο δείχνει κενά που μια λίστα ταξινομημένη μόνο σε στήθος, χέρια και πόδια μπορεί να χάσει. Δεν χρειάζεστε κάθε πρότυπο σε κάθε προπόνηση.`},{title:`Χτίζοντας μια ισορροπημένη εβδομάδα`,text:`Σε δύο ή τρεις συνεδρίες ολόκληρου του σώματος, ένας αρχάριος θα μπορούσε να περιλάβει μια καθισιά, μια άρθρωση ισχίου, μια οριζόντια ώθηση, μια οριζόντια έλξη, ένα προβάδισμα και μια απλή άσκηση κατά της περιστροφής ή της έκτασης. Η κάθετη ώθηση, η κάθετη έλξη και οι μεταφορές μπορούν να μπουν όταν το επιτρέπουν ο εξοπλισμός, η κινητικότητα και οι στόχοι σας. Κρατήστε τη δόση για κάθε πρότυπο αρκετά μικρή ώστε να αναρρώνετε, και παραλείψτε ασκήσεις που δεν χρειάζεστε.`},{title:`Προσαρμόστε τα πρότυπα στην ικανότητα`,text:`Κάθε πρότυπο έχει ευκολότερες και δυσκολότερες παραλλαγές. Μια καθισιά σε καρέκλα μπορεί να προηγηθεί ενός goblet squat, και μια κάμψη στον τοίχο μιας κάμψης στο πάτωμα. Μια κωπηλασία με καλώδιο και μια κωπηλασία με αλτήρα είναι και οι δύο οριζόντιες έλξεις, αλλά απαιτούν διαφορετική ισορροπία και εξοπλισμό. Αν μια κίνηση προκαλεί ενόχληση ή αισθάνεται ασταθής, αλλάξτε την παραλλαγή και κρατήστε το πρότυπο.`},{title:`Χρήση του TrainUp`,text:`Κάθε σελίδα άσκησης στο Explore δείχνει το κινητικό της πρότυπο, ώστε να ελέγξετε πώς η προγραμματισμένη εβδομάδα σας τα καλύπτει. Αν οι περισσότερες συνεδρίες έχουν ώθηση και σχεδόν καθόλου έλξη, μια κωπηλασία ή ένα κατέβασμα που ταιριάζει στον εξοπλισμό και στους περιορισμούς σας θα γέμιζε το κενό. Στοχεύστε σε καλή κάλυψη μέσα σε εβδομάδες, όχι σε τέλεια αναλογία σε κάθε συνεδρία.`}];var i=[{label:`NSCA: ασφάλεια και βασικές αρχές της προπόνησης με αντίσταση`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var l={sections:s,sources:i};export{l as default,s as sections,i as sources};